/*
 * A321103  Sequence generated by: a(3*n) = 1, a(3*n+2) = 2 - a(3*n+1),
 *          a(9*n+1) = 2, a(9*n+7) = 0, a(9*n+4) = 2 - a(3*n+1), for n >= 0.
 * https://oeis.org/A321103
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(3*n) = 1, a(3*n+2) = 2 - a(3*n+1), a(9*n+1) = 2, a(9*n+7) = 0,
 *            a(9*n+4) = 2 - a(3*n+1)
 * Range:     u8 n <= 200, u16 n <= 200, u32 n <= 200, u64 n <= 200,
 *            u128 n <= 200, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function computes A321103 for any n >= 0. */

seq_t a(idx_t n)
{
    /* Multiples of 3 */
    if (n % 3 == 0)
        return 1;

    /* n ≡ 1 (mod 3) */
    if (n % 3 == 1) {
        /* Resolve the 9–class subcase */
        switch (n % 9) {
        case 1: /* 9*n+1 */
            return 2;
        case 4: /* 9*n+4 */
            return 2 - a((n - 1) / 3);
        case 7: /* 9*n+7 */
            return 0;
        default: /* Should never occur */
            return 0;
        }
    }

    /* n ≡ 2 (mod 3) */
    /* a(3*n+2) = 2 - a(3*n+1) = 2 - a(n-1) */
    return 2 - a(n - 1);
}
